const catNames={"ctv": "CTV ADS", "static": "STATIC ADS", "ai": "AI-DRIVEN VIDEO", "ugc": "VIDEO ADS", "animated": "ANIMATED ADS", "editorial": "EDITORIAL DESIGN", "posters": "POSTERS", "logo": "LOGO", "longform": "LONG-FORM VIDEOS", "documentary": "DOCUMENTARY & INTERVIEWS"};
const world=document.querySelector("#world"), viewport=document.querySelector("#viewport"), filters=document.querySelector("#filters");
let current="all",tx=-1500,ty=-1100,scale=.62,drag=false,sx=0,sy=0,bx=0,by=0,moved=0;
const sizes={"9:16":[150,267],"16:9":[320,180],"4:5":[190,238],"1:1":[210,210],"2:3":[175,263]};
function visual(p,expanded=false){
  if(p.media && /\.(jpe?g|png|webp|gif|avif)$/i.test(p.media)){
    if(!expanded && p.cat==="static") {
      return `<div class="visual real-media static-portrait-preview"><img class="static-preview-bg" src="${p.media}" alt="" aria-hidden="true" loading="lazy"><img class="static-preview-main" src="${p.media}" alt="${p.title}" loading="lazy"></div><span class="caption">${p.title}</span>`;
    }
    return `<div class="visual real-media static-image"><img src="${p.media}" alt="${p.title}" loading="${expanded?"eager":"lazy"}"></div><span class="caption">${p.title}</span>`;
  }
  if(p.media){
    const attrs=expanded
      ? `controls autoplay playsinline preload="metadata"`
      : `muted loop autoplay playsinline preload="metadata"`;
    if(!expanded && (p.cat==="ctv" || p.cat==="longform")){
      return `<div class="visual real-media ctv-portrait-preview"><video class="ctv-preview-bg" muted loop autoplay playsinline preload="metadata" src="${p.media}"></video><video class="ctv-preview-main" ${attrs} src="${p.media}"></video></div><span class="caption">${p.title}</span>`;
    }
    return `<div class="visual real-media"><video ${attrs} src="${p.media}"></video></div><span class="caption">${p.title}</span>`;
  }
  return `<div class="visual"><b>${p.type}</b><strong>${String(p.n).padStart(2,"0")}</strong><small>${p.ratio} · PLACEHOLDER</small></div><span class="caption">${p.title}</span>`;
}
projects.forEach((p,i)=>{let b=document.createElement("button");b.className="tile";b.dataset.i=i;b.innerHTML=visual(p);world.appendChild(b)});
// The first Video Ad starts with dark frames: begin its muted thumbnail preview after the opening.
const firstAdPreview=world.querySelector(".tile[data-i=\""+projects.findIndex(p=>p.cat==="ugc"&&p.n===1)+"\"] video");
if(firstAdPreview){
  firstAdPreview.addEventListener("loadedmetadata",()=>{
    if(Number.isFinite(firstAdPreview.duration)&&firstAdPreview.duration>2){
      firstAdPreview.currentTime=Math.min(1.5,firstAdPreview.duration-0.25);
    }
  },{once:true});
}

const filterDefs=[["all","ALL"],...Object.entries(catNames)];
filterDefs.forEach(([key,label])=>{
  let b=document.createElement("button");
  b.dataset.filter=key;
  const count=key==="all"?projects.length:projects.filter(p=>p.cat===key).length;
  b.textContent=label+" "+count;
  if(key==="all")b.classList.add("active");
  b.onclick=()=>selectFilter(key,b);
  filters.appendChild(b)
});

function allLayout(items){
  // ALL = uniform 9:16 contact-sheet grid.
  // Every preview has identical dimensions and spacing so the repeated field is seamless.
  const cols=11;
  const w=150,h=267;
  const gapX=52,gapY=56;
  const stepX=w+gapX,stepY=h+gapY;
  const startX=360,startY=270;
  items.forEach((p,index)=>{
    const i=projects.indexOf(p);
    const col=index%cols,row=Math.floor(index/cols);
    place(i,startX+col*stepX,startY+row*stepY,w,h,true);
  });
}
function categoryLayout(items){
  // Category = one compact, mathematically centered row of five.
  // Equal horizontal gaps; the complete row is centered as one unit.
  const cx=1500,cy=1050;
  const cellW=270,gap=42;
  const cols=Math.min(5,items.length);
  const totalW=cols*cellW+(cols-1)*gap;
  const startX=cx-totalW/2;
  const maxH=300;
  const rows=Math.ceil(items.length/5);
  const rowStep=390;
  items.forEach((p,j)=>{
    const i=projects.indexOf(p);
    const [w0,h0]=sizes[p.ratio];
    const fit=Math.min(cellW/w0,maxH/h0);
    const w=w0*fit,h=h0*fit;
    const col=j%5,row=Math.floor(j/5);
    const rowCount=Math.min(5,items.length-row*5);
    const rowStart=cx-(rowCount*cellW+(rowCount-1)*gap)/2;
    const cellX=rowStart+col*(cellW+gap);
    place(i,cellX+(cellW-w)/2,cy+(row-(rows-1)/2)*rowStep-h/2,w,h,true);
  });
}
function place(i,x,y,w,h,show){const el=world.querySelector(`[data-i="${i}"]`);el.style.left=x+"px";el.style.top=y+"px";el.style.width=w+"px";el.style.height=h+"px";el.classList.toggle("hidden",!show)}
function layout(){
  const shown=current==="all"?projects:projects.filter(p=>p.cat===current);
  projects.forEach((p,i)=>{if(!shown.includes(p))world.querySelector(`[data-i="${i}"]`).classList.add("hidden")});
  current==="all"?allLayout(shown):categoryLayout(shown);
  document.querySelector("#viewName").textContent=current==="all"?"ALL WORK":catNames[current];
  document.querySelector("#viewCount").textContent=shown.length+" PROJECTS";
}
function selectFilter(key,b){current=key;filters.querySelectorAll("button").forEach(x=>x.classList.remove("active"));b.classList.add("active");layout();setTimeout(resetView,80)}
function apply(){world.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`}
function resetView(){
  const shown=[...world.querySelectorAll(".tile:not(.hidden):not(.tile-clone)")];
  if(!shown.length)return;

  const boxes=shown.map(el=>({
    x:parseFloat(el.style.left)||0,y:parseFloat(el.style.top)||0,
    w:parseFloat(el.style.width)||0,h:parseFloat(el.style.height)||0
  }));
  const minX=Math.min(...boxes.map(b=>b.x)),maxX=Math.max(...boxes.map(b=>b.x+b.w));
  const minY=Math.min(...boxes.map(b=>b.y)),maxY=Math.max(...boxes.map(b=>b.y+b.h));
  const cx=(minX+maxX)/2,cy=(minY+maxY)/2;

  if(current==="all"){
    // Baseline view: exactly the intended "three-row" overview.
    // This is also the hard minimum zoom: the user can only go IN from here.
    scale=.82;
  }else{
    // Fit the five-piece row with equal visual margins on all sides.
    const contentW=maxX-minX,contentH=maxY-minY;
    const padX=120,padY=165;
    scale=Math.min(
      .98,
      (window.innerWidth-padX*2)/contentW,
      (window.innerHeight-padY*2)/contentH
    );
    scale=Math.max(.72,scale);
  }

  tx=-cx*scale;
  ty=-cy*scale+(current==="all"?34:20);
  apply();
}
viewport.onpointerdown=e=>{
  if(e.button!==undefined && e.button!==0)return;
  drag=true;sx=e.clientX;sy=e.clientY;bx=tx;by=ty;moved=0;
  pressedTile=e.target.closest(".tile");
  viewport.classList.add("dragging");
};
viewport.onpointermove=e=>{
  if(!drag)return;
  const dx=e.clientX-sx,dy=e.clientY-sy;
  moved=Math.hypot(dx,dy);
  if(moved>4){tx=bx+dx;ty=by+dy;apply();}
};
viewport.onpointerup=e=>{
  if(!drag)return;
  const releasedTile=e.target.closest(".tile");
  const isClick=moved<7 && pressedTile && releasedTile===pressedTile;
  drag=false;viewport.classList.remove("dragging");
  if(isClick){
    const p=projects[Number(pressedTile.dataset.i)];
    openProject(p,pressedTile);
  }
  pressedTile=null;
};
viewport.onpointercancel=()=>{drag=false;pressedTile=null;viewport.classList.remove("dragging")};
viewport.addEventListener("wheel",e=>{
  e.preventDefault();
  const old=scale;
  const next=Math.max(current==='all'?.82:.72,Math.min(2.45,scale*(e.deltaY<0?1.065:.94)));
  const factor=next/old;
  // #world is anchored at 50% / 50% of the viewport.
  // Scale the pan offset itself so the visual center stays fixed.
  tx*=factor;
  ty*=factor;
  scale=next;
  apply();
},{passive:false});
function zoom(f){const old=scale,cx=innerWidth/2,cy=innerHeight/2;scale=Math.max(current==='all'?.82:.72,Math.min(2.45,scale*f));tx=cx-(cx-tx)*(scale/old);ty=cy-(cy-ty)*(scale/old);apply()}
document.querySelector("#plus").onclick=()=>zoom(1.14);document.querySelector("#minus").onclick=()=>zoom(.88);document.querySelector("#home").onclick=resetView;
document.querySelectorAll(".tile").forEach(el=>{
  const media=el.querySelector(".visual");
  media.addEventListener("pointermove",e=>{
    const r=media.getBoundingClientRect();
    media.style.setProperty("--mx",((e.clientX-r.left)/r.width*100)+"%");
    media.style.setProperty("--my",((e.clientY-r.top)/r.height*100)+"%");
  });
});
const modal=document.querySelector("#modal");
let activeProjectIndex=-1;

function viewerProjects(){
  return current==="all" ? projects : projects.filter(p=>p.cat===current);
}
function viewerIndexOf(p){
  return viewerProjects().indexOf(p);
}
function updateProjectNav(){
  const list=viewerProjects();
  const show=list.length>1;
  document.querySelector(".project-prev").style.display=show?"flex":"none";
  document.querySelector(".project-next").style.display=show?"flex":"none";
}
function navigateProject(dir){
  const list=viewerProjects();
  if(!list.length)return;
  const currentProject=projects[activeProjectIndex];
  let i=list.indexOf(currentProject);
  if(i<0)i=0;
  i=(i+dir+list.length)%list.length;
  const p=list[i];
  const source=[...world.querySelectorAll(".tile:not(.tile-clone)")].find(el=>Number(el.dataset.i)===projects.indexOf(p));
  openProject(p,source,true);
}
function openProject(p,sourceTile,fromNav=false){
  activeProjectIndex=projects.indexOf(p);
  {
    const list=viewerProjects();
    const n=list.indexOf(p);
    const count=document.querySelector(".project-count");
    if(count) count.textContent=(n>=0 ? `${n+1} / ${list.length}` : "");
  }
  updateProjectNav();
  const media=document.querySelector("#modalMedia");
  if(fromNav){
    media.classList.add("switching");
    document.querySelector(".project-copy").classList.add("switching");
  }
  media.innerHTML=`<div class="expanded-asset" data-ratio="${p.ratio}">${visual(p,true)}</div>`;
  document.querySelector("#modalCat").textContent=p.category+" / "+p.ratio;
  document.querySelector("#modalTitle").textContent=p.title;
  document.querySelector("#modalDesc").textContent=p.description || ("Selected work from "+p.category+".");
  document.querySelector("#modalRole").textContent=p.type;
  document.querySelector("#modalFormat").textContent=p.ratio;
  if(!modal.open){
    modal.classList.remove("is-open");
    modal.showModal();
  }
  if(sourceTile){
    const r=sourceTile.querySelector(".visual").getBoundingClientRect();
    modal.style.setProperty("--origin-x",(r.left+r.width/2)+"px");
    modal.style.setProperty("--origin-y",(r.top+r.height/2)+"px");
  }
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    enableExpandedAudio();
    modal.classList.add("is-open");
    media.classList.remove("switching");
    document.querySelector(".project-copy").classList.remove("switching");
  }));
}
document.querySelector(".project-prev").onclick=()=>navigateProject(-1);
document.querySelector(".project-next").onclick=()=>navigateProject(1);
window.addEventListener("keydown",e=>{
  if(!modal.open)return;
  if(e.key==="ArrowLeft")navigateProject(-1);
  if(e.key==="ArrowRight")navigateProject(1);
});
document.querySelector(".close").addEventListener("click",()=>stopExpandedAudio());
document.querySelector(".close").onclick=()=>{modal.classList.remove("is-open");setTimeout(()=>modal.close(),220)};modal.onclick=e=>{if(e.target===modal)modal.close()};
layout();resetView();window.addEventListener("resize",()=>resetView());

// ===== V2.7 — ALL-ONLY SEAMLESS GRID =====
let allClones=[];
function clearAllClones(){
  allClones.forEach(el=>el.remove());
  allClones=[];
}
function setupAllInfinite(){
  clearAllClones();
  if(current!=="all"){
    world.removeAttribute("data-period-x");
    world.removeAttribute("data-period-y");
    return;
  }

  const master=[...world.querySelectorAll(".tile:not(.hidden):not(.tile-clone)")];
  if(!master.length)return;

  // Exact grid period: 11 columns × 5 rows.
  // There is no extra boundary gap: the next copy starts at the same cadence.
  const w=150,h=267,gapX=52,gapY=56;
  const periodX=11*(w+gapX);
  const periodY=5*(h+gapY);
  world.dataset.periodX=periodX;
  world.dataset.periodY=periodY;

  for(let gy=-1;gy<=1;gy++){
    for(let gx=-1;gx<=1;gx++){
      if(gx===0&&gy===0)continue;
      master.forEach(source=>{
        const c=source.cloneNode(true);
        c.classList.add("tile-clone");
        c.dataset.master=source.dataset.i;
        c.style.left=((parseFloat(source.style.left)||0)+gx*periodX)+"px";
        c.style.top=((parseFloat(source.style.top)||0)+gy*periodY)+"px";
        c.style.width=w+"px";
        c.style.height=h+"px";
        const media=c.querySelector(".visual");
        media.addEventListener("pointermove",e=>{
          const r=media.getBoundingClientRect();
          media.style.setProperty("--mx",((e.clientX-r.left)/r.width*100)+"%");
          media.style.setProperty("--my",((e.clientY-r.top)/r.height*100)+"%");
        });
        c.addEventListener("click",e=>{
          e.stopPropagation();
          if(moved<7) openProject(projects[Number(c.dataset.master)],c);
        });
        world.appendChild(c);
        allClones.push(c);
      });
    }
  }
}

function wrapAllPan(){
  if(current!=="all")return;
  const px=(parseFloat(world.dataset.periodX)||0)*scale;
  const py=(parseFloat(world.dataset.periodY)||0)*scale;
  if(!px||!py)return;
  // Rebase by exact grid periods. Because the spacing cadence is identical at
  // the boundary, the wrap is visually continuous.
  while(tx>px/2)tx-=px;
  while(tx<-px/2)tx+=px;
  while(ty>py/2)ty-=py;
  while(ty<-py/2)ty+=py;
}

// Add wrapping to the existing drag behavior only in ALL.
const basePointerMove=viewport.onpointermove;
viewport.onpointermove=e=>{
  basePointerMove(e);
  if(drag&&moved>4&&current==="all"){
    wrapAllPan();
    apply();
  }
};

// Rebuild only after selecting ALL. Specific categories stay finite and centered.
const baseSelectFilter=selectFilter;
selectFilter=(key,b)=>{
  clearAllClones();
  baseSelectFilter(key,b);
  setTimeout(()=>{
    if(key==="all") setupAllInfinite();
  },650);
};

// Initial ALL copies.
setTimeout(setupAllInfinite,120);


// ===== V2.12 — APPROACH / DEPTH FOCUS =====
let approachTile=null;

function setApproachFocus(tile){
  if(modal.open)return;
  const shouldFocus=scale>=1.48 && tile;
  const allTiles=[...world.querySelectorAll(".tile:not(.hidden)")];

  if(!shouldFocus){
    approachTile=null;
    world.classList.remove("approaching");
    [...world.querySelectorAll(".tile")].forEach(el=>el.classList.remove("approach-focus","approach-neighbor"));
    return;
  }

  approachTile=tile;
  world.classList.add("approaching");

  const focusIndex=Number(tile.dataset.master ?? tile.dataset.i);
  allTiles.forEach(el=>{
    const index=Number(el.dataset.master ?? el.dataset.i);
    const same=index===focusIndex;
    el.classList.toggle("approach-focus",same);
    el.classList.toggle("approach-neighbor",!same);
  });

  // Continuous depth amount from subtle at 1.48 to strong near viewer entry.
  const t=Math.max(0,Math.min(1,(scale-1.48)/(2.28-1.48)));
  world.style.setProperty("--approach",t.toFixed(3));
}

function refreshApproachFromPointer(){
  if(modal.open){setApproachFocus(null);return}
  const el=document.elementFromPoint(pointerX,pointerY);
  setApproachFocus(el && el.closest ? el.closest(".tile") : null);
}

// ===== V2.9 — GENTLE POINTER TENDENCY + ZOOM-TO-SELECT =====
let pointerX=window.innerWidth/2,pointerY=window.innerHeight/2;
let autoVX=0,autoVY=0,targetVX=0,targetVY=0,pointerInside=false;
let hoveredTile=null;
let zoomSelectionLock=false;

viewport.addEventListener("pointerenter",()=>pointerInside=true);
viewport.addEventListener("pointerleave",()=>{
  pointerInside=false;targetVX=0;targetVY=0;hoveredTile=null;
});

viewport.addEventListener("pointermove",e=>{
  pointerX=e.clientX;pointerY=e.clientY;
  hoveredTile=e.target.closest(".tile");
  setApproachFocus(hoveredTile);
  if(current!=="all"||drag||modal.open){targetVX=0;targetVY=0;return;}

  const nx=(pointerX-innerWidth/2)/(innerWidth/2);
  const ny=(pointerY-innerHeight/2)/(innerHeight/2);
  const dead=.34;

  function tendency(v){
    const a=Math.abs(v);
    if(a<=dead)return 0;
    const t=Math.min(1,(a-dead)/(1-dead));
    // Very soft cubic ramp. This is only a directional tendency, not navigation.
    return Math.sign(v)*t*t*t;
  }

  const maxX=.72,maxY=.52;
  targetVX=-tendency(nx)*maxX;
  targetVY=-tendency(ny)*maxY;
});

function gentlePanLoop(){
  const enabled=current==="all"&&pointerInside&&!drag&&!modal.open;
  if(!enabled){targetVX=0;targetVY=0}

  // Long easing gives the floating / tendency feeling.
  autoVX+=(targetVX-autoVX)*.025;
  autoVY+=(targetVY-autoVY)*.025;
  if(Math.abs(autoVX)<.001)autoVX=0;
  if(Math.abs(autoVY)<.001)autoVY=0;

  if(enabled||autoVX||autoVY){
    tx+=autoVX;ty+=autoVY;
    if(current==="all")wrapAllPan();
    apply();
  }
  requestAnimationFrame(gentlePanLoop);
}
requestAnimationFrame(gentlePanLoop);

// Zooming deeply while the cursor is actually over a project behaves like
// physically approaching that project: it transitions into the project viewer.
viewport.addEventListener("wheel",e=>{
  if(modal.open||zoomSelectionLock)return;
  const tile=e.target.closest(".tile");
  if(!tile||e.deltaY>=0)return;
  if(scale>=2.28){
    zoomSelectionLock=true;
    const index=Number(tile.dataset.master ?? tile.dataset.i);
    setTimeout(()=>{
      openProject(projects[index],tile);
      zoomSelectionLock=false;
    },90);
  }
},{passive:true});

viewport.addEventListener("wheel",()=>{
  requestAnimationFrame(refreshApproachFromPointer);
},{passive:true});

// Dragging or filtering removes the depth treatment until the pointer settles again.
viewport.addEventListener("pointerdown",()=>setApproachFocus(null));
viewport.addEventListener("pointerup",()=>requestAnimationFrame(refreshApproachFromPointer));


// ===== V2.13 — ABOUT =====
const aboutModal=document.querySelector("#aboutModal");
const aboutTrigger=[...document.querySelectorAll("button,a")].find(el=>el.textContent.trim().toUpperCase()==="ABOUT");

if(aboutTrigger){
  aboutTrigger.addEventListener("click",e=>{
    e.preventDefault();
    aboutModal.showModal();
    requestAnimationFrame(()=>requestAnimationFrame(()=>aboutModal.classList.add("is-open")));
  });
}
document.querySelector(".about-close").onclick=()=>{
  aboutModal.classList.remove("is-open");
  setTimeout(()=>aboutModal.close(),260);
};
aboutModal.addEventListener("click",e=>{
  if(e.target===aboutModal){
    aboutModal.classList.remove("is-open");
    setTimeout(()=>aboutModal.close(),260);
  }
});
window.addEventListener("keydown",e=>{
  if(e.key==="Escape" && aboutModal.open){
    aboutModal.classList.remove("is-open");
    setTimeout(()=>aboutModal.close(),220);
  }
});


// ===== V2.28 — AUDIO LIFECYCLE =====
// Mosaic previews are always silent. Only the currently expanded project may play audio.
function muteMosaicPreviews(){
  document.querySelectorAll("#world video").forEach(v=>{
    v.muted=true;
    v.volume=0;
  });
}

function enableExpandedAudio(){
  // First guarantee there is no audio anywhere else.
  document.querySelectorAll("video").forEach(v=>{
    if(!v.closest("#modal")){
      v.muted=true;
      v.volume=0;
    }
  });

  const v=document.querySelector("#modal .expanded-asset video");
  if(v){
    v.muted=false;
    v.volume=1;
    const playPromise=v.play();
    if(playPromise && typeof playPromise.catch==="function"){
      playPromise.catch(()=>{});
    }
  }
}

function stopExpandedAudio(){
  document.querySelectorAll("#modal video").forEach(v=>{
    v.pause();
    v.muted=true;
    v.volume=0;
    try{v.currentTime=0}catch(e){}
  });
  muteMosaicPreviews();
}

// Keep previews silent from first render.
requestAnimationFrame(muteMosaicPreviews);

// Safety net: whenever the project dialog fully closes, kill its audio.
modal.addEventListener("close",stopExpandedAudio);

modal.addEventListener("cancel",()=>stopExpandedAudio());
